using Godot;
using System;
using System.Globalization;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioConductorControlOperations:RefCounted
{
    private static T Field<T>(GodotObject o,string key) where T:GodotObject=>(T)o.Get(key).AsGodotObject();
    private static GArray Points(Control o,string key)=>o.Get(key).AsGodotArray();
    private static double N(Settings point,string key)=>point[key].AsDouble();
    private static double Value(Control o,string key)=>Field<SpinBox>(o,key).Value;
    private static void Status(Control o,string text)=>Field<Godot.Label>(o,"_status").Text=text;
    private static RefCounted Draft(Control o)=>KiwiAudioConductor.create(o.Get("_tempo"),o.Get("_signature"),o.Get("_tempos"),o.Get("_meters"));
    public void label(Node parent,string text)=>parent.AddChild(new Godot.Label{Text=text,AutowrapMode=TextServer.AutowrapMode.WordSmart});
    private static void Button(Node parent,string text,System.Action action){var button=new Godot.Button{Text=text};parent.AddChild(button);button.Pressed+=action;}
    public SpinBox spin(Node parent,string text,double value,double low,double high,double step){label(parent,text);var control=new SpinBox{MinValue=low,MaxValue=high,Step=step,Value=value};parent.AddChild(control);return control;}
    public OptionButton denominator(Node parent,int selected){var choice=new OptionButton();parent.AddChild(choice);foreach(int value in new[]{1,2,4,8,16,32}){choice.AddItem("/ "+value);choice.SetItemMetadata(choice.ItemCount-1,value);if(value==selected)choice.Select(choice.ItemCount-1);}return choice;}
    public void setup(Control o,RefCounted session,double at)
    {
        o.Set("session",session);var document=session.Get("document").AsGodotObject();o.Set("_owner",document);o.Set("_revision",session.Get("revision"));o.Set("_tempo",document.Get("tempo"));o.Set("_signature",document.Get("time_signature"));o.Set("_tempos",document.Get("tempo_points").AsGodotArray().Duplicate(true));o.Set("_meters",document.Get("meter_points").AsGodotArray().Duplicate(true));label(o,"Project conductor / grid. Points use quarter-note beats from zero; tempo changes are steps. Every meter point starts a new bar, closing any partial bar.");label(o,"Conductor edits preserve all clip positions, source windows, audio and MIDI source timing. Piano roll and generated sections retain source-relative beats. This does not warp audio or make patterns follow tempo changes.");var initial=new HFlowContainer();o.AddChild(initial);var signature=o.Get("_signature").AsVector2I();var bpm=spin(initial,"Initial BPM",o.Get("_tempo").AsDouble(),20,400,.01);bpm.ValueChanged+=value=>{o.Set("_tempo",value);refresh_lists(o);};var numerator=spin(initial,"Initial meter",signature.X,1,32,1);numerator.ValueChanged+=value=>{var next=o.Get("_signature").AsVector2I();next.X=(int)value;o.Set("_signature",next);refresh_lists(o);};var denominatorControl=denominator(initial,signature.Y);denominatorControl.ItemSelected+=index=>{var next=o.Get("_signature").AsVector2I();next.Y=denominatorControl.GetItemMetadata((int)index).AsInt32();o.Set("_signature",next);refresh_lists(o);};
        var tabs=new TabContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};o.AddChild(tabs);var tempos=new VBoxContainer{Name="Tempo points"};tabs.AddChild(tempos);var tempoList=Field<ItemList>(o,"_tempos_list");tempoList.CustomMinimumSize=new Vector2(0,145);tempoList.SizeFlagsVertical=Control.SizeFlags.ExpandFill;tempos.AddChild(tempoList);var tempoRow=new HFlowContainer();tempos.AddChild(tempoRow);using var conductor=document.Call("conductor").As<RefCounted>();using var ops=new AudioConductorOperations();double beat=ops.seconds_to_beat(conductor,at);o.Set("_tempo_beat",spin(tempoRow,"Quarter beat",Math.Max(.001,beat),.001,10000000,.001));o.Set("_tempo_value",spin(tempoRow,"BPM",ops.tempo_at(conductor,at),20,400,.01));Button(tempoRow,"Add / replace at beat",()=>put_tempo(o));Button(tempoRow,"Move selected",()=>move_tempo(o));Button(tempoRow,"Remove selected",()=>remove_tempo(o));tempoList.ItemSelected+=index=>{var point=Points(o,"_tempos")[(int)index].AsGodotDictionary();Field<SpinBox>(o,"_tempo_beat").Value=N(point,"beat");Field<SpinBox>(o,"_tempo_value").Value=N(point,"bpm");};tempoList.ItemActivated+=index=>seek(o,N(Points(o,"_tempos")[(int)index].AsGodotDictionary(),"beat"));
        var meters=new VBoxContainer{Name="Meter points"};tabs.AddChild(meters);var meterList=Field<ItemList>(o,"_meters_list");meterList.CustomMinimumSize=new Vector2(0,145);meterList.SizeFlagsVertical=Control.SizeFlags.ExpandFill;meters.AddChild(meterList);var meterRow=new HFlowContainer();meters.AddChild(meterRow);o.Set("_meter_beat",spin(meterRow,"Quarter beat",Math.Max(.001,beat),.001,10000000,.001));o.Set("_meter_numerator",spin(meterRow,"Meter",4,1,32,1));var meterDenominator=denominator(meterRow,4);o.Set("_meter_denominator",meterDenominator);Button(meterRow,"Add / replace at beat",()=>put_meter(o));Button(meterRow,"Move selected",()=>move_meter(o));Button(meterRow,"Remove selected",()=>remove_meter(o));meterList.ItemSelected+=index=>{var point=Points(o,"_meters")[(int)index].AsGodotDictionary();Field<SpinBox>(o,"_meter_beat").Value=N(point,"beat");Field<SpinBox>(o,"_meter_numerator").Value=N(point,"numerator");for(int i=0;i<meterDenominator.ItemCount;i++)if(meterDenominator.GetItemMetadata(i).AsInt32()==(int)N(point,"denominator"))meterDenominator.Select(i);};meterList.ItemActivated+=index=>seek(o,N(Points(o,"_meters")[(int)index].AsGodotDictionary(),"beat"));label(o,"Double-click a point to seek its draft time. Apply replaces the conductor in one undo step; closing this window discards the draft. Reopen after any other document edit.");var status=Field<Godot.Label>(o,"_status");status.AutowrapMode=TextServer.AutowrapMode.WordSmart;o.AddChild(status);Button(o,"Apply conductor (preserve source timing)",()=>apply(o));refresh_lists(o);
    }
    private static void Sort(GArray points){var sorted=new System.Collections.Generic.List<Settings>();foreach(var raw in points)sorted.Add(raw.AsGodotDictionary());sorted.Sort((a,b)=>N(a,"beat").CompareTo(N(b,"beat")));points.Clear();foreach(var point in sorted)points.Add(point);}
    private static Settings Tempo(Control o)=>new(){["beat"]=Value(o,"_tempo_beat"),["bpm"]=Value(o,"_tempo_value")};
    private static Settings Meter(Control o){var choice=Field<OptionButton>(o,"_meter_denominator");return new Settings{["beat"]=Value(o,"_meter_beat"),["numerator"]=(int)Value(o,"_meter_numerator"),["denominator"]=choice.GetItemMetadata(choice.Selected).AsInt32()};}
    public void put_tempo(Control o)=>put(o,Points(o,"_tempos"),Tempo(o));
    public void put_meter(Control o)=>put(o,Points(o,"_meters"),Meter(o));
    public void move_tempo(Control o)=>move(o,Points(o,"_tempos"),Field<ItemList>(o,"_tempos_list"),Tempo(o));
    public void move_meter(Control o)=>move(o,Points(o,"_meters"),Field<ItemList>(o,"_meters_list"),Meter(o));
    public void move(Control o,GArray points,ItemList list,Settings point){var selected=list.GetSelectedItems();if(selected.Length==0){Status(o,"Select a point to move first.");return;}for(int i=0;i<points.Count;i++)if(i!=selected[0]&&Math.Abs(N(points[i].AsGodotDictionary(),"beat")-N(point,"beat"))<.000001){Status(o,"That beat already has a point. Use Add / replace at beat to replace it.");return;}points[selected[0]]=point;Sort(points);refresh_lists(o);}
    public void put(Control o,GArray points,Settings point){for(int i=0;i<points.Count;i++)if(Math.Abs(N(points[i].AsGodotDictionary(),"beat")-N(point,"beat"))<.000001){points[i]=point;refresh_lists(o);return;}if(points.Count>=1024){Status(o,"This conductor lane already has 1024 points.");return;}points.Add(point);Sort(points);refresh_lists(o);}
    public void remove_tempo(Control o){var selected=Field<ItemList>(o,"_tempos_list").GetSelectedItems();if(selected.Length>0){Points(o,"_tempos").RemoveAt(selected[0]);refresh_lists(o);}}
    public void remove_meter(Control o){var selected=Field<ItemList>(o,"_meters_list").GetSelectedItems();if(selected.Length>0){Points(o,"_meters").RemoveAt(selected[0]);refresh_lists(o);}}
    public void refresh_lists(Control o){using var conductor=Draft(o);using var ops=new AudioConductorOperations();Status(o,conductor.Get("error").AsString());var tempos=Field<ItemList>(o,"_tempos_list");var meters=Field<ItemList>(o,"_meters_list");tempos.Clear();meters.Clear();string F(double number,string format)=>number.ToString(format,CultureInfo.InvariantCulture);foreach(var raw in Points(o,"_tempos")){var point=raw.AsGodotDictionary();tempos.AddItem("Q "+F(N(point,"beat"),"F3")+" · "+F(N(point,"bpm"),"F2")+" BPM · "+F(ops.beat_to_seconds(conductor,N(point,"beat")),"F3")+" s");}foreach(var raw in Points(o,"_meters")){var point=raw.AsGodotDictionary();meters.AddItem("Q "+F(N(point,"beat"),"F3")+" · "+(int)N(point,"numerator")+"/"+(int)N(point,"denominator")+" · "+F(ops.beat_to_seconds(conductor,N(point,"beat")),"F3")+" s");}}
    private static bool Current(Control o){var session=Field<RefCounted>(o,"session");return o.Call("_owner_current").AsBool()&&session.Get("document").AsGodotObject()==o.Get("_owner").AsGodotObject()&&session.Get("revision").AsInt64()==o.Get("_revision").AsInt64();}
    public void seek(Control o,double beat){if(!Current(o)){Status(o,"The composition changed. Close and reopen this editor.");return;}using var conductor=Draft(o);if(conductor.Get("error").AsString().Length==0){using var ops=new AudioConductorOperations();o.EmitSignal("seek_requested",ops.beat_to_seconds(conductor,beat));}}
    public void apply(Control o){var session=Field<RefCounted>(o,"session");if(!Current(o)||session.Get("_before").AsGodotObject()!=null){Status(o,"The composition changed. Close and reopen this editor before applying.");return;}using var edits=new AudioEditSessionOperations();string problem=edits.set_conductor(session,o.Get("_tempo").AsDouble(),o.Get("_signature").AsVector2I(),Points(o,"_tempos"),Points(o,"_meters"));if(problem.Length>0){Status(o,problem);return;}o.EmitSignal("applied");}
}
